/* Signature Latin Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Marcellus Augustus": "Built in tria-nomina style: praenomen + nomen + cognomen.", "Juliana Livia": "Feminine compound of Juliana + Livia.", "Gaius Fortis": "From fortis (brave): 'brave Gaius'.", "Cornelia Clara": "From clara (bright).", "Aurelius Verus": "From aureus (golden) + verus (true).", "Livia Serena": "From serena (calm).", "Fortisius": "Signature gens-style surname: 'of the brave'.", "Clarentius": "Signature gens-style surname.", "Aurelianus": "Signature gens-style surname.", "Serenatius": "Signature gens-style surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Marcellus Augustus';
console.log(lookup(q));

